#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7;
const int BITMASK=1<<20;
int n,mask_limit,final_output,p1_array[BITMASK],p2_array[BITMASK];
int grid_flag[10][10],grid_a[10][10],h_code[10][10][10];

int fast_pow(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res=1LL*res*base%MOD;
        base=1LL*base*base%MOD;
        exp>>=1;
    }
    return res;
}

int get_mod_inverse(int x) { return fast_pow(x,MOD-2); }

bool is_valid_triplet(int x,int y,int z) {
    int arr[3]={x,y,z},perm[3]={0,1,2};
    do {
        if (grid_flag[arr[perm[0]]][1] && grid_flag[arr[perm[1]]][2] && grid_flag[arr[perm[2]]][3]) return true;
    } while (next_permutation(perm,perm+3));
    return false;
}

void process_first_phase(int P,int x,int y) {
    if (x==7 && y==1) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (is_valid_triplet(i,j,k)) {
                        int X=1;
                        while (X==i || X==j || X==k) X++;
                        int Y=X+1;
                        while (Y==i || Y==j || Y==k) Y++;
                        int Z=Y+1;
                        while (Z==i || Z==j || Z==k) Z++;
                        state|=h_code[X][Y][Z];
                    }
        p1_array[state]=(p1_array[state]+P)%MOD;
        return;
    }
    grid_flag[x][y]=1;
    if (y==3) process_first_phase(1LL*P*grid_a[x][y]%MOD,x+1,1);
    else process_first_phase(1LL*P*grid_a[x][y]%MOD,x,y+1);
    grid_flag[x][y]=0;
    if (y==3) process_first_phase(1LL*P*(MOD+1-grid_a[x][y])%MOD,x+1,1);
    else process_first_phase(1LL*P*(MOD+1-grid_a[x][y])%MOD,x,y+1);
}

void process_second_phase(int P,int x,int y) {
    if (x==7 && y==4) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (is_valid_triplet(i,j,k)) state|=h_code[i][j][k];
        p2_array[state]=(p2_array[state]+P)%MOD;
        final_output=(final_output+1LL*p1_array[mask_limit^state]*P)%MOD;
        return;
    }
    grid_flag[x][y-3]=1;
    if (y==6) process_second_phase(1LL*P*grid_a[x][y]%MOD,x+1,4);
    else process_second_phase(1LL*P*grid_a[x][y]%MOD,x,y+1);
    grid_flag[x][y-3]=0;
    if (y==6) process_second_phase(1LL*P*(MOD+1-grid_a[x][y])%MOD,x+1,4);
    else process_second_phase(1LL*P*(MOD+1-grid_a[x][y])%MOD,x,y+1);
}

int main() {
    scanf("%d",&n);
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            scanf("%d",&grid_a[i][j]),grid_a[i][j]=1LL*grid_a[i][j]*get_mod_inverse(100)%MOD;
    for (int i=n+1; i<=6; i++) grid_a[i][i]=1;
    int total=0;
    for (int i=1; i<=6; i++)
        for (int j=i+1; j<=6; j++)
            for (int k=j+1; k<=6; k++) 
                h_code[i][j][k]=1<<total++;
    process_first_phase(1,1,1);
    mask_limit=(1<<20)-1;
    for (int i=0; i<=19; i++)
        for (int j=0; j<=mask_limit; j++) 
            if (j>>i&1) p1_array[j]=(p1_array[j]+p1_array[j^1<<i])%MOD;
    process_second_phase(1,1,4);
    final_output=(MOD+1-final_output)%MOD;
    printf("%d\n",final_output);
    return 0;
}
